class Solution:
    def arrayNesting(self, nums: list[int]) -> int:
        best = 0
        for start in range(len(nums)):
            seen, current = set(), start
            while current not in seen:
                seen.add(current)
                current = nums[current]
            best = max(best, len(seen))
        return best
